"""Complete per-owner shared TargetRenderer descriptions; explicit dictionary output only."""
from pathlib import Path
import argparse,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
DEFAULT_PREFIX='liquidbounce.module.autoBow.bowAimbot.targetRendering'
LABELS={'TargetRendering':'目标渲染','Legacy':'经典','Circle':'圆环','Image':'图片','GlowingCircle':'发光圆环','Ghost':'幽影','Hearts':'环绕爱心','Text2D':'二维文字','Arrow':'箭头','HeightMode':'高度模式','Feet':'脚部','Top':'顶部','Relative':'相对高度','Health':'生命值','Animated':'动态','Source':'来源','Custom':'自定义','Builtin':'内置','Preset':'预设','Marker1':'标记一','Marker2':'标记二','ColorModulator':'颜色调制','Rotate':'旋转曲线','Period':'周期','Symmetric':'对称往返','Curve':'曲线','OuterColor':'外侧颜色','InnerColor':'内侧颜色','InnerRadius':'内半径','ExtraYOffset':'额外高度','GlowColor':'渐隐端颜色','GlowHeight':'辉光高度','HeightMultiplier':'高度振幅','HeightOffset':'高度基准','GlowOffset':'辉光相位','DynamicCount':'动态数量','HeartCount':'爱心数量','Orbit':'轨道','SqueezeStrength':'受伤收缩强度','SqueezeSpeed':'受伤收缩速度','CanBeCovered':'可被遮挡','OutlineColor':'轮廓颜色'}
LABELS_TW={'TargetRendering':'目標繪製','Legacy':'經典','Circle':'圓環','Image':'圖片','GlowingCircle':'發光圓環','Ghost':'幽影','Hearts':'環繞愛心','Text2D':'二維文字','Arrow':'箭頭','HeightMode':'高度模式','Feet':'腳部','Top':'頂部','Relative':'相對高度','Health':'生命值','Animated':'動態','Source':'來源','Custom':'自訂','Builtin':'內建','Preset':'預設','Marker1':'標記一','Marker2':'標記二','ColorModulator':'色彩調制','Rotate':'旋轉曲線','Period':'週期','Symmetric':'對稱往返','Curve':'曲線','OuterColor':'外側色彩','InnerColor':'內側色彩','InnerRadius':'內半徑','ExtraYOffset':'額外高度','GlowColor':'漸隱端色彩','GlowHeight':'輝光高度','HeightMultiplier':'高度振幅','HeightOffset':'高度基準','GlowOffset':'輝光相位','DynamicCount':'動態數量','HeartCount':'愛心數量','Orbit':'軌道','SqueezeStrength':'受傷收縮強度','SqueezeSpeed':'受傷收縮速度','CanBeCovered':'可被遮擋','OutlineColor':'輪廓色彩'}
MODES={'Legacy':['Size','Height','Color','ExtraYOffset'],'Circle':['Radius','InnerRadius','OuterColor','InnerColor','Color'],'Image':['Source','Source.Custom','Source.Custom.File','Source.Builtin','Source.Builtin.Preset','Scale','ColorModulator','Rotate','Rotate.Period','Rotate.Symmetric','Rotate.Curve'],'GlowingCircle':['Radius','OuterColor','GlowColor','GlowHeight','Color'],'Ghost':['Color','Size','Length'],'Hearts':['Color','DynamicCount','HeartCount','YOffset','Size','Orbit','Orbit.Radius','Orbit.Speed','Orbit.SqueezeStrength','Orbit.SqueezeSpeed','CanBeCovered'],'Text2D':['Scale','Shadow','Color','Text'],'Arrow':['Color','OutlineColor','Size']}
HEIGHT=['HeightMode','HeightMode.Feet','HeightMode.Feet.Offset','HeightMode.Top','HeightMode.Top.Offset','HeightMode.Relative','HeightMode.Relative.Height','HeightMode.Health','HeightMode.Animated','HeightMode.Animated.Speed','HeightMode.Animated.HeightMultiplier','HeightMode.Animated.HeightOffset','HeightMode.Animated.GlowOffset']
HELP={'':'为实际选中的目标绘制标记；每个功能独立保存参数和爱心动画。','Enabled':'启用此目标标记。','Mode':'选择经典方块、圆环、图片、发光圆环、幽影、爱心、二维文字或箭头；默认发光圆环。','HeightMode':'选择脚部、顶部、相对高度、生命值高度或动态高度。','Feet':'脚部高度加偏移。','Top':'实际实体包围盒高度加偏移。','Relative':'以实体实际高度的比例定位。','Health':'以当前生命值除以最大生命值的比例定位；非生物高度为零。','Animated':'按实体实际年龄与渲染插值计算正弦高度。','Offset':'在选定高度上追加偏移，单位为方块。','HeightMultiplier':'正弦运动的高度振幅。','HeightOffset':'正弦运动的高度基准，不乘实体高度。','GlowOffset':'发光圆环渐隐端的正弦相位差。','Source':'自定义 PNG/JPG 文件或两张原版内置图片；默认自定义。','Custom':'使用所选图片文件；尚未选择有效图片时不绘制。','Builtin':'使用原始 LiquidBounce 标记素材。','File':'选择 PNG、JPG 或 JPEG 图片；读取失败时保留上一张成功图片。','Preset':'选择第一张或第二张原始标记图片。','Rotate':'图片绕相机朝向的局部 Z 轴按曲线旋转。','Period':'曲线单程周期，单位毫秒。','Symmetric':'到达曲线终点后反向播放；关闭时直接循环。','Curve':'横轴为归一化进度，纵轴为角度；保持原版张力 0.4。','Scale':'缩放标记；图片使用独立的 X/Y 缩放，文字使用统一缩放。','ColorModulator':'与图片像素颜色相乘的 ARGB 调制色。','OuterColor':'圆环外侧或辉光底部的 ARGB 颜色。','InnerColor':'圆环内侧的 ARGB 颜色。','InnerRadius':'圆环留空半径，修改时不得超过当前外半径。','Radius':'圆环或轨道半径，单位为方块。','GlowColor':'发光圆环另一端的 ARGB 颜色；默认透明。','GlowHeight':'非动态高度模式下辉光的垂直高度，可设为负值。','ExtraYOffset':'经典方块在实体顶部的额外偏移。','DynamicCount':'按目标当前生命值计算爱心数量与部分填充。','HeartCount':'关闭动态数量时的普通爱心数量；吸收爱心仍追加。','Orbit':'爱心围绕目标的运动参数。','SqueezeStrength':'受到伤害时爱心轨道收缩的强度。','SqueezeSpeed':'根据实际受伤计时控制收缩与恢复窗口。','CanBeCovered':'使爱心接受真实场景深度测试。','Length':'三条幽影流各自的片段数；每片透明度递减 15。','Text':'按行绘制文字，使用原主题原生字体，水平居中、垂直居中。','Shadow':'在文字后方绘制偏移两像素的半透明黑色阴影。','OutlineColor':'箭头边线颜色；默认透明。','Color':'标记的 ARGB 颜色，包含透明度。','Size':'标记尺寸；爱心保持原心形宽高比。','Height':'经典方块高度，或相对于实体的高度比例。','YOffset':'爱心的额外垂直偏移。','Speed':'动画速度；轨道速度单位为度／秒。'}
HELP_TW={'':'為實際選中的目標繪製標記；每個功能獨立儲存參數與愛心動畫。','Enabled':'啟用此目標標記。','Mode':'選擇經典方塊、圓環、圖片、發光圓環、幽影、愛心、二維文字或箭頭；預設發光圓環。','HeightMode':'選擇腳部、頂部、相對高度、生命值高度或動態高度。','Feet':'腳部高度加偏移。','Top':'實際實體包圍盒高度加偏移。','Relative':'以實體實際高度的比例定位。','Health':'以目前生命值除以最大生命值的比例定位；非生物高度為零。','Animated':'按實體實際年齡與繪製插值計算正弦高度。','Offset':'在選定高度上追加偏移，單位為方塊。','HeightMultiplier':'正弦運動的高度振幅。','HeightOffset':'正弦運動的高度基準，不乘實體高度。','GlowOffset':'發光圓環漸隱端的正弦相位差。','Source':'自訂 PNG/JPG 檔案或兩張原版內建圖片；預設自訂。','Custom':'使用所選圖片檔案；尚未選擇有效圖片時不繪製。','Builtin':'使用原始 LiquidBounce 標記素材。','File':'選擇 PNG、JPG 或 JPEG 圖片；讀取失敗時保留上一張成功圖片。','Preset':'選擇第一張或第二張原始標記圖片。','Rotate':'圖片繞相機朝向的局部 Z 軸按曲線旋轉。','Period':'曲線單程週期，單位毫秒。','Symmetric':'到達曲線終點後反向播放；關閉時直接循環。','Curve':'橫軸為正規化進度，縱軸為角度；保留原版張力 0.4。','Scale':'縮放標記；圖片使用獨立 X/Y 縮放，文字使用統一縮放。','ColorModulator':'與圖片像素色彩相乘的 ARGB 調制色。','OuterColor':'圓環外側或輝光底部的 ARGB 色彩。','InnerColor':'圓環內側的 ARGB 色彩。','InnerRadius':'圓環留空半徑，修改時不得超過目前外半徑。','Radius':'圓環或軌道半徑，單位為方塊。','GlowColor':'發光圓環另一端的 ARGB 色彩；預設透明。','GlowHeight':'非動態高度模式下輝光的垂直高度，可設為負值。','ExtraYOffset':'經典方塊在實體頂部的額外偏移。','DynamicCount':'按目標目前生命值計算愛心數量與部分填滿。','HeartCount':'關閉動態數量時的一般愛心數量；吸收愛心仍追加。','Orbit':'愛心圍繞目標的運動參數。','SqueezeStrength':'受到傷害時愛心軌道收縮的強度。','SqueezeSpeed':'依實際受傷計時控制收縮與恢復視窗。','CanBeCovered':'使愛心接受真實場景深度測試。','Length':'三條幽影流各自的片段數；每片透明度遞減 15。','Text':'逐行繪製文字，使用原主題原生字型，水平置中、垂直置中。','Shadow':'在文字後方繪製偏移兩像素的半透明黑色陰影。','OutlineColor':'箭頭邊線色彩；預設透明。','Color':'標記的 ARGB 色彩，包含透明度。','Size':'標記尺寸；愛心保留原心形寬高比。','Height':'經典方塊高度，或相對於實體的高度比例。','YOffset':'愛心的額外垂直偏移。','Speed':'動畫速度；軌道速度單位為度／秒。'}
def paths():
 out=['','Enabled','Mode']
 for mode,fields in MODES.items():
  out.append('Mode.'+mode);out.extend('Mode.'+mode+'.'+f for f in fields)
  if mode in ['Circle','Image','GlowingCircle','Text2D']:out.extend('Mode.'+mode+'.'+f for f in HEIGHT)
 return out
def descriptions(language,prefix=DEFAULT_PREFIX):
 help=HELP_TW if language=='zh_tw'else HELP;out={}
 for path in paths():
  k=prefix+(''.join('.'+p[:1].lower()+p[1:]for p in path.split('.'))if path else'')+'.description';name=path.rsplit('.',1)[-1]
  text=help.get(path,help.get(name,('绘制'+LABELS.get(name,name)+'目标标记。')if language!='zh_tw'else('繪製'+LABELS_TW.get(name,name)+'目標標記。')))
  if language=='en_us':text=f'{path or "TargetRendering"}: source TargetRenderer parameter; independent owner state and inactive-mode values are retained.'
  out[k]=text
 return out
def update(language,target,prefix=DEFAULT_PREFIX):
 data=json.loads(target.read_text(encoding='utf8'));data['labels'].update(LABELS_TW if language=='zh_tw'else LABELS);data['descriptions'].update(descriptions(language,prefix))
 if language=='zh_cn':data['englishDescriptions'].update(descriptions('en_us',prefix))
 target.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--directory',required=True);p.add_argument('--prefix',default=DEFAULT_PREFIX);a=p.parse_args()
 for lang in ['zh_cn','zh_tw']:update(lang,ROOT/a.directory/f'display_{lang}.json',a.prefix)
